mapper.select:
SELECT DISTINCT '${params.tableName}' as downFileName , b.PATH , ifnull(c.ZLMC,REVERSE(SUBSTR(REVERSE(b.PATH),1,POSITION(REVERSE(b.PATH),'/')-1))) AS FILE_NAME ,'${params.S_INFO_ID}' AS S_INFO_ID FROM ${params.table} a LEFT JOIN ods.PT_GY_FILES b ON a.UUID=b.PCUUID LEFT JOIN ods.PT_GY_TSZL c ON c.ZLNO=b.PCUUID where 1=1
AND a.ATTA_ID = #{params.ATTA_ID}
AND a.${params.info} = #{params.S_INFO_ID}
limit 5
